            item.className = 'nav-item' + ((idx === 0 && !(config.startSlide && config.startSlide !== 'none')) ? ' active' : '');
            item.setAttribute('data-id', record.id);
            var num = document.createElement('span'); num.className = 'nav-num'; num.innerText = (idx + 1);
